CREATE TABLE IF NOT EXISTS uat_seed_state (seed_key VARCHAR(100) PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now(), description TEXT);
DO $$
DECLARE nhrc UUID; grants UUID; finance UUID; procurement UUID; lab UUID; director UUID; grants_user UUID; researcher UUID; finance_user UUID; procurement_user UUID; lab_user UUID; f1 UUID; f2 UUID; rp UUID; opp1 UUID; opp2 UUID; app1 UUID; award1 UUID; partner1 UUID; award_partner1 UUID;
BEGIN
IF NOT EXISTS (SELECT 1 FROM uat_seed_state WHERE seed_key='UAT_V010') THEN
 SELECT id INTO nhrc FROM organisation_units WHERE code='NHRC';
 SELECT id INTO grants FROM organisation_units WHERE code='GRANTS'; SELECT id INTO finance FROM organisation_units WHERE code='FINANCE'; SELECT id INTO procurement FROM organisation_units WHERE code='PROC'; SELECT id INTO lab FROM organisation_units WHERE code='LAB';
 SELECT id INTO director FROM users WHERE email='director.uat@nhrc.local'; SELECT id INTO grants_user FROM users WHERE email='grants.uat@nhrc.local'; SELECT id INTO researcher FROM users WHERE email='researcher.uat@nhrc.local'; SELECT id INTO finance_user FROM users WHERE email='finance.uat@nhrc.local'; SELECT id INTO procurement_user FROM users WHERE email='procurement.uat@nhrc.local'; SELECT id INTO lab_user FROM users WHERE email='laboratory.uat@nhrc.local';
END IF; END $$;
